import{_ as t,c as e,o as a,a4 as i}from"./chunks/framework.BCDg3NR7.js";const o="/yue-blog-public/assets/image-20250103162602623.q66zT-VX.png",s="/yue-blog-public/assets/image-20250103162549750.CBk6hC3D.png",l="/yue-blog-public/assets/image-20250103162729035.C5DRO_hM.png",r="/yue-blog-public/assets/image-20250103162825723.DNiaXdVp.png",c="/yue-blog-public/assets/image-20250103162854492.DYufdRBp.png",d="/yue-blog-public/assets/image-20250103162917404.CAB_Hi7d.png",g="/yue-blog-public/assets/image-20250103162957627.LF4PJoqW.png",p="/yue-blog-public/assets/image-20250103164318273.BsvvXcas.png",n="/yue-blog-public/assets/image-20250103164332994.Duyw8iuP.png",h="/yue-blog-public/assets/image-20250103164358444.Csad87hR.png",m="/yue-blog-public/assets/image-20250103164410872.B1cLeiyj.png",u="/yue-blog-public/assets/image-20250103164441822.C-i2xWCM.png",b="/yue-blog-public/assets/image-20250103164522244.Czx0qR5E.png",_="/yue-blog-public/assets/image-20250103164533728.DBQ1InxX.png",q="/yue-blog-public/assets/image-20250103164737822.liHsAUMb.png",f="/yue-blog-public/assets/image-20250103164838577.DEv1zmX-.png",x="/yue-blog-public/assets/image-20250103165120575.CYbJ7-BO.png",k="/yue-blog-public/assets/image-20250103165218282.TR5xFZeQ.png",y="/yue-blog-public/assets/image-20250103165308809.prQGuweV.png",P="/yue-blog-public/assets/image-20250103165343270.DCYY_cet.png",C="/yue-blog-public/assets/image-20250103165509071.DU_uLpr-.png",G="/yue-blog-public/assets/image-20250103165548161.PYdz9FMr.png",v="/yue-blog-public/assets/image-20250103165707134.BClElS4M.png",S="/yue-blog-public/assets/image-20250103165733791.B9I0iuyx.png",D="/yue-blog-public/assets/image-20250103165800476.CZmnZIHF.png",B="/yue-blog-public/assets/1712634803620-3f65f793-ab1c-4d12-b4df-9272ad68ecaf.BxPJkD7x.gif",E="/yue-blog-public/assets/1712278910007-278e9284-cae4-46d7-b32b-89810a7f1359.DWMIvtYV.gif",A="/yue-blog-public/assets/image-20250103165931272.NsDt_h87.png",w="/yue-blog-public/assets/image-20250103170012947.CdUh9e6u.png",H="/yue-blog-public/assets/image-20250106081251134.DuF8KhaY.png",L="/yue-blog-public/assets/image-20250106081331421.BVhLWXQu.png",V="/yue-blog-public/assets/image-20250106081406439.Cw74QHYM.png",R="/yue-blog-public/assets/image-20250106081423627.Vwa0VW5t.png",F="/yue-blog-public/assets/image-20250103164101269.CnJRsgce.png",I="/yue-blog-public/assets/image-20250103164034126.9rJn73ch.png",T="/yue-blog-public/assets/image-20250103163948671.CqyrlJgN.png",Y="/yue-blog-public/assets/image-20250103163730453.BRH-QZlb.png",N="/yue-blog-public/assets/image-20250103163714085.Cbrb7u8V.png",J="/yue-blog-public/assets/image-20250103163641976.D9SGbb4N.png",M="/yue-blog-public/assets/image-20250103163539086.CvvKLLtC.png",W="/yue-blog-public/assets/image-20250103163247222.Blw9g2AX.png",X="/yue-blog-public/assets/image-20250103163234385.Ba-5HtWb.png",it=JSON.parse('{"title":"Git 快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"articles/07-others/代码规范/Git 快速上手.md","filePath":"articles/07-others/代码规范/Git 快速上手.md","lastUpdated":1736390926000}'),z={name:"articles/07-others/代码规范/Git 快速上手.md"},Q=i('<h1 id="git-快速上手" tabindex="-1">Git 快速上手 <a class="header-anchor" href="#git-快速上手" aria-label="Permalink to &quot;Git 快速上手&quot;">​</a></h1><h1 id="一、git-简介" tabindex="-1">一、Git 简介 <a class="header-anchor" href="#一、git-简介" aria-label="Permalink to &quot;一、Git 简介&quot;">​</a></h1><p>Git 是一款版本控制系统，它可以<strong>追踪文件的更改</strong>，并能<strong>多人协同开发</strong>，它最初由 Linus Torvalds 在 2005 年为更好地管理 Linux 内核而设计的； Git 是目前最流行的版本控制系统，主要功能有：</p><ul><li>代码备份</li><li>版本回退</li><li>协同开发</li><li>权限控制</li></ul><h1 id="二、下载安装" tabindex="-1">二、下载安装 <a class="header-anchor" href="#二、下载安装" aria-label="Permalink to &quot;二、下载安装&quot;">​</a></h1><p>下载地址：<a href="https://git-scm.com/" target="_blank" rel="noreferrer">https://git-scm.com/</a> ，随后“傻瓜式”安装（一路下一步即可）</p><p><strong>注意：如果自定义安装路径，切记路径中不要包含中文！</strong></p><h1 id="三、git-基本使用" tabindex="-1">三、Git 基本使用 <a class="header-anchor" href="#三、git-基本使用" aria-label="Permalink to &quot;三、Git 基本使用&quot;">​</a></h1><h2 id="_1-起始配置" tabindex="-1">1. 起始配置 <a class="header-anchor" href="#_1-起始配置" aria-label="Permalink to &quot;1. 起始配置&quot;">​</a></h2><p>第一次使用 Git 的时候，我们需要配置<strong>姓名</strong>和<strong>邮箱</strong>，让 Git 知道当前开发者的基本信息</p><p>配置姓名：</p><div class="language-git vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">git</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>git config --global user.name &quot;Your Name&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>配置邮箱：</p><div class="language-git vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">git</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>git config --global user.email &quot;email@example.com&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>注意点：</p><ol><li>命令中的各单词中间有空格。</li><li>上述两个命令只在第一次使用 Git 时运行, 若输入错误, 重新运行命令即可。</li><li>可以使用 <code>git config --list</code>或<code>git config -l</code>命令来查看配置信息 。</li><li>上述这两个命令不用自己手敲, 直接复制粘贴，随后修改【姓名】与【邮箱】即可。</li></ol><h2 id="_2-linux-常用命令" tabindex="-1">2. linux 常用命令 <a class="header-anchor" href="#_2-linux-常用命令" aria-label="Permalink to &quot;2. linux 常用命令&quot;">​</a></h2><p>Windows 为图形化操作形式，Linux 一般使用命令与系统进行交互，常用的命令如下：</p><table><thead><tr><th>命令</th><th>含义</th></tr></thead><tbody><tr><td><code>mkdir</code></td><td>创建文件夹（make directory）</td></tr><tr><td><code>cd</code></td><td>改变工作目录，（change directory 缩写）</td></tr><tr><td><code>touch</code></td><td>创建一个文件</td></tr><tr><td><code>ls</code></td><td>查看文件夹下的文件 （list 单词的缩写）</td></tr><tr><td><code>cat</code></td><td>查看文件内容</td></tr><tr><td><code>Tab</code></td><td>路径自动补全</td></tr><tr><td><code>clear</code></td><td>清屏（也可以使用 <code>ctrl + L</code> 快捷键）</td></tr><tr><td><code>rm</code></td><td>删除文件或文件夹 （删除不会进入回收站） -r 递归删除（用来删除文件夹）</td></tr><tr><td><code>ctrl + c</code></td><td>取消命令 c cancel 缩写</td></tr><tr><td><code>上下方向键</code></td><td>查看命令历史</td></tr></tbody></table><h2 id="_3-vim-编辑器" tabindex="-1">3. vim 编辑器 <a class="header-anchor" href="#_3-vim-编辑器" aria-label="Permalink to &quot;3. vim 编辑器&quot;">​</a></h2><p>Vim 是一款命令行下的文本编辑器，编辑方式跟图形化编辑器不同，基本操作</p><ol><li>命令行 <code>vim 文件名</code> 打开文件</li><li>按<code>i</code>进入编辑模式</li><li>开始编辑文件内容</li><li><code>ESC</code> + <code>:wq</code> 保存并退出（w =&gt; write q=&gt;quit）</li><li><code>ESC</code> + <code>:q!</code> 不保存并退出</li></ol><h2 id="_4-git-的三个区" tabindex="-1">4. Git 的三个区 <a class="header-anchor" href="#_4-git-的三个区" aria-label="Permalink to &quot;4. Git 的三个区&quot;">​</a></h2><p>以生活中做菜为例，整个过程中涉及到三个区域：① 货架、② 购物车、③ 厨房</p><p><img src="'+o+'" alt="image-20250103162602623"></p><p>Git 中同样也分为三个区域，分别是：</p><ol><li>工作区（代码编辑区）</li><li>暂存区（暂时存储区）</li><li>版本区（版本控制区）</li></ol><p><img src="'+s+'" alt="image-20250103162549750"></p><p>工作区、暂存区、版本区，三个区共同组成了一个 <strong>Git 仓库</strong></p><h2 id="_5-基本操作流程" tabindex="-1">5. 基本操作流程 <a class="header-anchor" href="#_5-基本操作流程" aria-label="Permalink to &quot;5. 基本操作流程&quot;">​</a></h2><p>**第一步：**创建一个空文件夹（名称不要包含中文），随后双击打开文件夹。</p><p>**第二步：**在文件夹空白处右键 ，随后点击open git bash here 启动命令行。</p><p>**第三步：**创建一个 Git 仓库，命令为：<code>git init</code>，命令执行成后，提示如下：</p><p><img src="'+l+'" alt="image-20250103162729035"></p><p><code>git init</code>执行后，会出现一个.git文件夹，这表示当前文件夹已成为一个 Git 仓库。</p><p>**第四步：**创建一些文件并编写代码，比如创建 【a.txt】，此时工作区已经有了新文件。</p><p>**第五步：**把工作区中【a.txt】添加到暂存区，具体命令为：<code>git add a.txt</code>，此命令无提示。</p><p>补充：<code>git add -A</code>可以把工作区中的所有文件，都添加到暂存区，比较常用。</p><p>**第六步：**把暂存区【a.txt】添加到版本区，具体命令为：<code>git commit -m &#39;xxx&#39;</code>，随后提示如下：</p><p><img src="'+r+'" alt="image-20250103162825723"></p><p>注意：此时我们先不用关心上图中的具体提示，后面会详细讲解。</p><p><strong>关键步骤图示：</strong></p><p><img src="'+c+'" alt="image-20250103162854492"></p><h2 id="_6-git-三区的位置" tabindex="-1">6. Git 三区的位置 <a class="header-anchor" href="#_6-git-三区的位置" aria-label="Permalink to &quot;6. Git 三区的位置&quot;">​</a></h2><p>Git 的三区位置大致如下（了解即可）</p><p><img src="'+d+'" alt="image-20250103162917404"></p><h2 id="_7-查看仓库状态" tabindex="-1">7. 查看仓库状态 <a class="header-anchor" href="#_7-查看仓库状态" aria-label="Permalink to &quot;7. 查看仓库状态&quot;">​</a></h2><p><code>git status</code>命令用于显示仓库当前的状态，<code>git status -s</code>也用于查看仓库状态，但提示更为简短。</p><p><img src="'+g+'" alt="image-20250103162957627"></p><h2 id="_8-删除暂存" tabindex="-1">8. 删除暂存 <a class="header-anchor" href="#_8-删除暂存" aria-label="Permalink to &quot;8. 删除暂存&quot;">​</a></h2><p><code>git rm --cached &lt;file&gt;</code>可以将文件<strong>从暂存区中删除</strong>。</p><p><img src="'+p+'" alt="image-20250103164318273"></p><h2 id="_9-对比差异" tabindex="-1">9. 对比差异 <a class="header-anchor" href="#_9-对比差异" aria-label="Permalink to &quot;9. 对比差异&quot;">​</a></h2><p><code>git diff</code>用于对比：<strong>工作区</strong> vs <strong>暂存区</strong></p><p><code>git diff --cached</code> 用于对比：<strong>暂存区</strong> vs <strong>仓库区</strong></p><p>diff 命令的返回格式如下图：</p><p><img src="'+n+'" alt="image-20250103164332994"></p><p>注意：实际开发中文件多，且修改内容也多，我们会借助 git 的 GUI 工具进行文件差异对比。</p><h2 id="_10-查看版本日志" tabindex="-1">10. 查看版本日志 <a class="header-anchor" href="#_10-查看版本日志" aria-label="Permalink to &quot;10. 查看版本日志&quot;">​</a></h2><p>借助于下面命令，可以查看整个 git 的提交记录</p><ol><li><p><code>git log</code>：按提交时间降序列出所有提交，最新的提交会首先显示。</p></li><li><p><img src="'+h+'" alt="image-20250103164358444"></p></li><li><p><code>git log --oneline</code>：在<code>git log</code>的基础上，以简洁的一行显示每个提交。</p></li><li><p><img src="'+m+'" alt="image-20250103164410872"></p></li></ol><p>如果内容偏多， 需要使用方向键上下滚动， 按 q 退出。</p><h2 id="_11-版本回退" tabindex="-1">11. 版本回退 <a class="header-anchor" href="#_11-版本回退" aria-label="Permalink to &quot;11. 版本回退&quot;">​</a></h2><p>Git 可以将项目代码内容切换到历史的任何一个版本，使用 <code>git reset --hard 版本号</code></p><p>使用场景如下：</p><ol><li><p>创建一个 git 仓库，随后创建：a、b、c、d 四个文件</p></li><li><p><img src="'+u+'" alt="image-20250103164441822"></p></li><li><p>随后对四个文件，分别依次执行：<code>git add</code>、<code>git commit</code>进行版本控制</p></li><li><p>随后使用<code>git log --online</code>查看版本记录</p></li></ol><p><img src="'+b+'" alt="image-20250103164522244"></p><ol><li>现在我们使用<code>git reset --hard 版本号</code>把代码回滚到：刚提交完 b 文件的时候</li></ol><p><img src="'+_+'" alt="image-20250103164533728"></p><ol><li>两个注意点：</li></ol><p>注意点 1：<code>git reset --hard</code>会有如下动作：</p><p>① 切换<strong>版本区</strong> HEAD （指针）指向</p><p>② 还原<strong>暂存区</strong>到对应版本</p><p>③ 还原<strong>工作区</strong>到对应版本执行<code>git reset --hard</code>之前，最好进行： <code>git add</code> 、<code>git commit</code>操作！</p><p>--soft：重置HEAD到指定提交，所有的更改都会自动添加到暂存区，对工作区无影响。</p><p>--mixed (默认值)：重置HEAD到指定的提交，并且重置暂存区，对工作区无影响。</p><p>--hard：重置HEAD到指定的提交，并且重置暂存区，重置工作区！</p><p>注意点 2：使用<code>git reset --hard</code>版本回滚后，使用<code>git log</code>只能看到当前版本之前的记录，例如：刚才回到了<code>**13f46ca**</code>这个版本，那使用<code>git log --online</code>就会看到：<img src="'+q+'" alt="image-20250103164737822">此时：看不见 c 文件和 d 文件的提交记录了，因为对于<strong>13f46ca</strong> 这个版本来说，c 文件和 d 文件的提交记录属于<strong>未来</strong>，是看不到的，要想看到最完整的日志记录，可以使用<code>git reflog</code>命令。<img src="'+f+'" alt="image-20250103164838577"></p><h2 id="_12-修改提交" tabindex="-1">12. 修改提交 <a class="header-anchor" href="#_12-修改提交" aria-label="Permalink to &quot;12. 修改提交&quot;">​</a></h2><p><code>git commit --amend</code> 命令可以修改最近一次提交，它可以：</p><ol><li>重新编辑上次的提交信息。</li></ol><p>​ 如果在一次提交后，意识到提交信息有误或不够详细，可以使用 <code>git commit --amend</code> 来重新编辑上次提交信息</p><ol><li>将新的更改添加到上次提交中。</li></ol><p>​ 如果在一次提交后，意识到忘记将某文件提交了，可以先使用 <code>git add</code> 将这些遗漏的更改添加到暂存区，然后通过 <code>git commit --amend</code> 将它们添加到上一个提交中。</p><p><strong>场景演示</strong></p><p><img src="'+x+'" alt="image-20250103165120575"></p><p><img src="'+k+'" alt="image-20250103165218282"></p><h2 id="_13-忽略文件" tabindex="-1">13. 忽略文件 <a class="header-anchor" href="#_13-忽略文件" aria-label="Permalink to &quot;13. 忽略文件&quot;">​</a></h2><p>在项目开发过程中有些文件<strong>不应该存储到版本库中</strong>，这个时候配置忽略这些文件。</p><p>git 中需要创建一个文件 『<code>.gitignore</code>』文件来设置忽略，『<code>.gitignore</code>』文件与<code>.git</code> 目录同级，常用规则如下：</p><table><thead><tr><th>内容</th><th>含义</th></tr></thead><tbody><tr><td><code>temp</code></td><td>忽略<strong>任何路径下</strong>的名为 temp 的<strong>文件</strong>、<strong>文件夹。</strong></td></tr><tr><td><code>*.log</code></td><td>忽略<strong>任何路径下</strong>以<code>.log</code> 结尾的文件。</td></tr><tr><td><code>/dist</code></td><td>忽略根目录下的 <code>dist</code> 文件，不会忽略其他目录下的 <code>dist</code> 文件</td></tr></tbody></table><p>备注：<code>.gitkeep</code>文件可以把空文件夹提交</p><h2 id="_14-分支" tabindex="-1">14. 分支 <a class="header-anchor" href="#_14-分支" aria-label="Permalink to &quot;14. 分支&quot;">​</a></h2><h3 id="_14-1-分支的概念" tabindex="-1">14.1. 分支的概念 <a class="header-anchor" href="#_14-1-分支的概念" aria-label="Permalink to &quot;14.1. 分支的概念&quot;">​</a></h3><p>分支是 git 的一个重要特性，它可以让开发人员<strong>从主线上分离出来，在一个独立的线路上继续开发</strong>，最后可以灵活的选择合并分支，还是丢弃分支。用一个生活中的例子，来理解分支：</p><p><img src="'+y+'" alt="image-20250103165308809"></p><p>比如我们正在写一本小说，这本小说的<strong>当前内容</strong>就像是 git 中的 <strong>master 分支</strong>**，**现在我们有几个新的想法，比如：新的角色、新的剧情，但不确定这些是否最终一定出现在故事里，所以我们可以这样做：</p><ol><li>可以为每个新的想法，创建一个新的<strong>笔记本</strong>（一个笔记本就相当于 git 中的<strong>一个新分支</strong>）</li><li>每个笔记本（分支）中都可以自由地探索想法，且不会搅乱你的当前内容（master 分支）</li><li>当我们觉得一个剧情线非常好，并且想要将其包含在故事中时，就会把那个笔记本的内容（分支）合并到你的当前内容（master 分支）中。</li><li>如果某个想法实验失败，可以选择抛弃那个笔记本（相当于 git 中的删除分支），且这个过程不会影响当前内容（master分支）</li></ol><h3 id="_14-2-创建与切换分支" tabindex="-1">14.2. 创建与切换分支 <a class="header-anchor" href="#_14-2-创建与切换分支" aria-label="Permalink to &quot;14.2. 创建与切换分支&quot;">​</a></h3><p><img src="'+P+'" alt="image-20250103165343270"></p><ul><li>注意点如下：</li></ul><p>① 切换分支前，最好把当前分支管理好，即最好进行：<code>add</code>、<code>commit</code>操作。</p><p>② 切换分支后，工作区、暂存区、会受到影响，具体为：</p><p>工作区：会变为<strong>切换到的</strong>分支的<strong>最后一次提交的状态</strong></p><p>暂存区：同上，且如果暂存区有未提交的更改，那这些更改会被带到新分支的暂存区上。</p><p><strong>比如：在 test 分支对 x 文件进行了暂存，没提交，随后切换到 master 分支时，x 文件会自动加在 master 分支的暂存区</strong></p><h3 id="_14-3-合并分支-快速合并" tabindex="-1">14.3. 合并分支（快速合并） <a class="header-anchor" href="#_14-3-合并分支-快速合并" aria-label="Permalink to &quot;14.3. 合并分支（快速合并）&quot;">​</a></h3><p>例如我们有 master 和 test 两个分支，test 分支是领先于 master 分支的，且 tets 分支包含 master 的所有历史记录，那么这时就可以触发 git 的快速合并，具体演示如下：</p><p><img src="'+C+'" alt="image-20250103165509071"></p><p><img src="'+G+'" alt="image-20250103165548161"></p><h3 id="_14-4-合并分支-提交合并" tabindex="-1">14.4. 合并分支（提交合并） <a class="header-anchor" href="#_14-4-合并分支-提交合并" aria-label="Permalink to &quot;14.4. 合并分支（提交合并）&quot;">​</a></h3><p>场景描述：当进行分支合并时，若两个分支有不一致的版本，则会提示输提示输入提交信息，在当前分支形成一个新的提交记录，具体场景请执行上述<code>14.3</code>的<strong>前三步</strong>，然后接下来执行下面步骤：</p><p><img src="'+v+'" alt="image-20250103165707134"></p><p><img src="'+S+'" alt="image-20250103165733791"></p><h3 id="_14-5-删除分支" tabindex="-1">14.5. 删除分支 <a class="header-anchor" href="#_14-5-删除分支" aria-label="Permalink to &quot;14.5. 删除分支&quot;">​</a></h3><p><img src="'+D+'" alt="image-20250103165800476"></p><h3 id="_14-6-分支变基" tabindex="-1">14.6. 分支变基 <a class="header-anchor" href="#_14-6-分支变基" aria-label="Permalink to &quot;14.6. 分支变基&quot;">​</a></h3><p>在 Git 中，合并（merge）和变基（rebase）都是用于整合来自不同分支的更改的操作，它们区别如下：</p><ul><li>合并（merge）：</li></ul><p>将两个分支的历史合并在一起，gti 会创建一个新的“合并提交”，所有的分支和合并点都会被保留在历史中，有完整的历史记录。</p><p><img src="'+B+'" alt="img"></p><ul><li>变基（rebase）</li></ul><p>将一个分支（test）上的提交重新应用到另一个分支（master）上，变基会重写项目历史，因为它实际上是在创建一系列新的提交，会产生一个更线性的历史记录，看起来更干净、更简单。<img src="'+E+'" alt="img"></p><h3 id="_14-7-tag-标签" tabindex="-1">14.7. tag（标签） <a class="header-anchor" href="#_14-7-tag-标签" aria-label="Permalink to &quot;14.7. tag（标签）&quot;">​</a></h3><p>在Git中，标签（Tag）是用来指向特定提交的引用，通常用于标记项目中的重要点，比如版本发布。标签分为两种类型：</p><ol><li>轻量标签（Lightweight）</li></ol><p>轻量标签只是简单地指向一个提交，不包含其他信息，创建轻量标签不会存储任何额外的信息。</p><ol><li>附注标签（Annotated）</li></ol><p>附注标签存储了额外的信息，例如：标签名、标签信息、创建者名字、电子邮件、创建日期等。因为它们包含了更多的信息，附注标签更适用于公共或正式发布的场合，比如软件版本的发布。</p><p>创建标签</p><p>命令作用<code>git tag 标签名 版本号</code>给指定提交打 <strong>轻量标签</strong><code>git tag -a 标签名 版本号 -m &quot;标签描述&quot;</code>给指定提交打 <strong>附注标签****上述两个命令可以不写版本号，不写就是给最新提交打标签</strong><code>git tag</code>查看标签<code>git show 标签名</code>查看标签信息<code>git tag -d 标签名</code>删除标签</p><h3 id="_14-8-游离分支" tabindex="-1">14.8. 游离分支 <a class="header-anchor" href="#_14-8-游离分支" aria-label="Permalink to &quot;14.8. 游离分支&quot;">​</a></h3><p><code>git checkout</code>也可以将代码签出到指定版本，即可以执行<code>git checkout 具体版本号</code>，当签出到指定版本时，签出的代码出于一个游离分支中，如下图操作：</p><p><img src="'+A+'" alt="image-20250103165931272"></p><p>游离分支上可以对代码进行版本控制，但要注意：一旦从游离分支切走，游离分支的提交不会交给任何一个分支，所以对于游离分支我们的原则是：</p><ol><li>尽量不修改游离分支的代码（只是看一看某个版本的代码）。</li><li>若确实需要修改游离分支代码，应该从当前游离分支，创建出一个新的分支，随后去修改。</li><li>若修在游离分支上发生了提交，随后从游离分支切走了，就要使用 reflog 寻找游离分支的提交。</li></ol><h2 id="_16-gitflow" tabindex="-1">16. GitFlow <a class="header-anchor" href="#_16-gitflow" aria-label="Permalink to &quot;16. GitFlow&quot;">​</a></h2><p>GitFlow 是团队开发的一种最佳实践，将代码划分为以下几个分支</p><p><img src="'+w+'" alt="image-20250103170012947"></p><table><thead><tr><th>分支</th><th>含义</th></tr></thead><tbody><tr><td><code>master</code></td><td>主分支，只保存<strong>正式发布</strong>的代码。</td></tr><tr><td><code>develop</code></td><td>开发分支，开发者的编写的代码最终要出现在这个分支。</td></tr><tr><td><code>hotfix</code></td><td>线上 bug 修复分支，修复完毕后要合并回 master 和 develop 分支，同时在 master 分支上打一个tag。</td></tr><tr><td><code>feature</code></td><td>功能分支，当开发某个功能时创建一个单独的分支，开发完毕后再合并到 dev 分支。</td></tr><tr><td><code>release</code></td><td>待发布分支，Release分支基于Develop分支创建，在这个Release分支上测试。</td></tr></tbody></table><h1 id="四-ssh-协议" tabindex="-1">四. SSH 协议 <a class="header-anchor" href="#四-ssh-协议" aria-label="Permalink to &quot;四. SSH 协议&quot;">​</a></h1><h3 id="_1-公钥加密" tabindex="-1">1. 公钥加密 <a class="header-anchor" href="#_1-公钥加密" aria-label="Permalink to &quot;1. 公钥加密&quot;">​</a></h3><p>我们来举个例子，你在 <strong>A 城市</strong>，想给你在 <strong>B 城市</strong>的朋友张三发送一个机密的信件，由于工作原因，你无法亲自去送，同时你也担心快递不能严格的保密。这时你就可以使用公钥加密技术，大致思路是：</p><ul><li>张三先给你<strong>一个特制的保险箱（公钥）****，<strong>这个保险箱 <strong>仅有一把</strong> 能打开它的钥匙，钥匙在张三那里</strong>。</strong></li><li>你将信件放入保险箱并锁上，随后交给快递员，快递员携带着这个箱子去送货，但 <strong>无法打开</strong> 它。</li><li>快递到达，**张三手里的钥匙（私钥）**打开保险箱，取出信件。</li></ul><p><strong>总结：</strong></p><ol><li>通过这种方式，即使在不完全可信的通道上，你的信件也能安全到达目的地，没有人能够在途中打开保险箱并窃取它。这就是公钥加密的工作原理。</li><li>使用公钥（所有人可见的保险箱）来加密信息，而只有对应的私钥（只有接收者持有的钥匙）能解密信息。这种方法不仅保护了数据的安全性，还确保了数据传输的私密性和完整性。</li></ol><h3 id="_2-ssh-简介" tabindex="-1">2. SSH 简介 <a class="header-anchor" href="#_2-ssh-简介" aria-label="Permalink to &quot;2. SSH 简介&quot;">​</a></h3><p>SSH（Secure Shell）是一种网络协议，SSH利用公钥加密技术提供了一种安全的方法，来管理和操作远程计算机，保护数据的安全和隐私</p><h3 id="_3-gitee-使用-ssh" tabindex="-1">3. Gitee 使用 ssh <a class="header-anchor" href="#_3-gitee-使用-ssh" aria-label="Permalink to &quot;3. Gitee 使用 ssh&quot;">​</a></h3><p><img src="'+H+'" alt="image-20250106081251134"></p><p><img src="'+L+'" alt="image-20250106081331421"></p><p><img src="'+V+'" alt="image-20250106081406439"></p><h1 id="五、vscode-中使用-git" tabindex="-1">五、VSCode 中使用 git <a class="header-anchor" href="#五、vscode-中使用-git" aria-label="Permalink to &quot;五、VSCode 中使用 git&quot;">​</a></h1><h2 id="_1-插件推荐" tabindex="-1">1. 插件推荐 <a class="header-anchor" href="#_1-插件推荐" aria-label="Permalink to &quot;1. 插件推荐&quot;">​</a></h2><p>VSCode 中有很多 git 相关的插件，本教程中推荐下面两个：</p><p><img src="'+R+'" alt="image-20250106081423627"></p><h2 id="_2-创建仓库" tabindex="-1">2. 创建仓库 <a class="header-anchor" href="#_2-创建仓库" aria-label="Permalink to &quot;2. 创建仓库&quot;">​</a></h2><p>如图所示点击操作，即可借助<code>Vscode</code>来创建仓库</p><p><img src="'+F+'" alt="image-20250103164101269"></p><p>不同的工具创建出来的主分支名字可能不一样，比如 Vscode 中通过点击下方按钮创建的仓库，主分支的名字就叫<code>main</code>，当然也可以进行修改，让 Vscode 默认的主分支名是 <code>master</code></p><h2 id="_3-版本控制" tabindex="-1">3. 版本控制 <a class="header-anchor" href="#_3-版本控制" aria-label="Permalink to &quot;3. 版本控制&quot;">​</a></h2><p><img src="'+I+'" alt="image-20250103164034126"></p><h2 id="_4-撤销暂存" tabindex="-1">4. 撤销暂存 <a class="header-anchor" href="#_4-撤销暂存" aria-label="Permalink to &quot;4. 撤销暂存&quot;">​</a></h2><p>点击“-”撤销对 b 文件的暂存</p><p><img src="'+T+'" alt="image-20250103163948671"></p><h2 id="_5-版本回退" tabindex="-1">5. 版本回退 <a class="header-anchor" href="#_5-版本回退" aria-label="Permalink to &quot;5. 版本回退&quot;">​</a></h2><p>借助 Git Graph 以游离分支的形式回退（本质是 <code>git checkout 版本号</code>）</p><p>借助 Git History 版本回退（本质是 <code>git reset --hard 版本号</code>或 <code>git reset --soft 版本号</code>）</p><h2 id="_6-添加-tag" tabindex="-1">6. 添加 tag <a class="header-anchor" href="#_6-添加-tag" aria-label="Permalink to &quot;6. 添加 tag&quot;">​</a></h2><p><img src="'+Y+'" alt="image-20250103163730453"></p><h2 id="_7-创建分支" tabindex="-1">7. 创建分支 <a class="header-anchor" href="#_7-创建分支" aria-label="Permalink to &quot;7. 创建分支&quot;">​</a></h2><p><img src="'+N+'" alt="image-20250103163714085"></p><h2 id="_8-分支合并" tabindex="-1">8. 分支合并 <a class="header-anchor" href="#_8-分支合并" aria-label="Permalink to &quot;8. 分支合并&quot;">​</a></h2><p>在当前分支上鼠标右键，随后选择将当前分支合并到哪个分支</p><p><img src="'+J+'" alt="image-20250103163641976"></p><p>选择 Yes,merge</p><h2 id="_9-分支变基" tabindex="-1">9. 分支变基 <a class="header-anchor" href="#_9-分支变基" aria-label="Permalink to &quot;9. 分支变基&quot;">​</a></h2><p>分支变基是指将一个分支上的提交（commit）按照原有次序依次应用到另一个分支上，从而整合两个分支的修改。</p><ul><li><p><strong>目的</strong>：</p><ol><li><p>合并代码：将不同分支上的代码修改合并到一起，形成一个统一的代码库。</p></li><li><p>解决冲突：通过变基操作，可以更容易地解决分支之间的冲突，避免复杂的合并过程。</p></li><li><p>保持代码整洁：变基可以使得提交历史更加线性、清晰，便于理解和维护。</p><p>二、操作过程</p><ul><li><strong>找到共同祖先</strong>：首先找到两个分支（即当前分支和目标基底分支）的最近共同祖先。</li><li><strong>提取修改</strong>：然后对比当前分支相对于该祖先的历次提交，提取相应的修改并存为临时文件。</li><li><strong>应用修改</strong>：将当前分支指向目标基底，然后依次将之前提取的修改应用到目标基底上。</li><li><img src="'+M+'" alt="image-20250103163539086"></li></ul></li></ol></li></ul><h2 id="_10-推送代码、拉取代码" tabindex="-1">10. 推送代码、拉取代码 <a class="header-anchor" href="#_10-推送代码、拉取代码" aria-label="Permalink to &quot;10. 推送代码、拉取代码&quot;">​</a></h2><p><img src="'+W+'" alt="image-20250103163247222"></p><h2 id="_11-处理冲突" tabindex="-1">11. 处理冲突 <a class="header-anchor" href="#_11-处理冲突" aria-label="Permalink to &quot;11. 处理冲突&quot;">​</a></h2><p><img src="'+X+'" alt="image-20250103163234385"></p><h1 id="六、附录" tabindex="-1">六、附录 <a class="header-anchor" href="#六、附录" aria-label="Permalink to &quot;六、附录&quot;">​</a></h1><h2 id="_1-git-官方书籍" tabindex="-1">1. Git 官方书籍 <a class="header-anchor" href="#_1-git-官方书籍" aria-label="Permalink to &quot;1. Git 官方书籍&quot;">​</a></h2><p><a href="https://git-scm.com/book/zh/v2/%E8%B5%B7%E6%AD%A5-%E5%85%B3%E4%BA%8E%E7%89%88%E6%9C%AC%E6%8E%A7%E5%88%B6" target="_blank" rel="noreferrer">https://git-scm.com/book/zh/v2/</a></p><h2 id="_2-git-目录介绍" tabindex="-1">2. git 目录介绍 <a class="header-anchor" href="#_2-git-目录介绍" aria-label="Permalink to &quot;2. git 目录介绍&quot;">​</a></h2><ul><li>hooks 目录包含客户端或服务端的钩子脚本，在特定操作下自动执行</li><li>info 信息文件夹. 包含一个全局性排除文件，可以配置文件忽略</li><li>logs 保存日志信息</li><li>objects 目录存储所有数据内容,本地的版本库存放位置</li><li>refs 目录存储指向数据的提交对象的指针（分支）</li><li>config 文件包含项目特有的配置选项</li><li>description 用来显示对仓库的描述信息</li><li>HEAD 文件指示目前被检出的分支</li><li>index 暂存区文件，是一个二进制文件 (git ls-files)</li></ul><p>切记： 不要手动去修改 .git 文件夹中的内容</p><h2 id="_3-crlf" tabindex="-1">3. CRLF <a class="header-anchor" href="#_3-crlf" aria-label="Permalink to &quot;3. CRLF&quot;">​</a></h2><p>CRLF 是Carriage-Return Line-Feed 的缩写。</p><p>CR 表示的是 ASCII 码的第 13 个符号 \\r 回车，LF 表示的是 ASCII 码表的第 10 个符号 \\n 换行。</p><p>每个操作系统对回车换行的存储方式不同</p><ul><li>windows 下用 CRLF（\\r\\n）表示</li><li>linux 和 unix 下用 LF（\\n）表示</li><li>mac 系统下用 CR（\\r）表示</li></ul><h2 id="_4-卸载密码管理工具" tabindex="-1">4. 卸载密码管理工具 <a class="header-anchor" href="#_4-卸载密码管理工具" aria-label="Permalink to &quot;4.  卸载密码管理工具&quot;">​</a></h2><p>执行命令： <code>git config --system --unset credential.helper</code></p>',196),U=[Q];function Z($,O,j,K,tt,et){return a(),e("div",null,U)}const ot=t(z,[["render",Z]]);export{it as __pageData,ot as default};
